import AppKit

/// Official provider marks (Lobe Icons, MIT; TypeSafe from typesafe.ai),
/// embedded so the app needs no resource bundle. Single-colour templates —
/// the UI tints them. Regenerate rather than hand-edit.
enum ProviderLogo {
    @MainActor private static var cache: [String: NSImage] = [:]

    /// The template image for a catalog template id, or nil (custom servers).
    @MainActor static func image(_ id: String) -> NSImage? {
        if let hit = cache[id] { return hit }
        let data: Data? = if id == "typesafe" { Data(base64Encoded: typesafePNG) } else { svg[id].map { Data($0.utf8) } }
        guard let data, let img = NSImage(data: data) else { return nil }
        img.isTemplate = true
        cache[id] = img
        return img
    }

